53	  writeFiles(root, {
54	    '.claudinite-settings.json': JSON.stringify({ packs: ['demo'] }),
55	    'packs/demo/tasks/demo-task/task.md': '# demo task\n',
56	    'packs/demo/tasks/demo-task/task.json': taskJson('demo-task'),
57	    'packs/undeclared/tasks/rogue-task/task.md': '# rogue task\n',
