73	function environment(root, { event, eventPath, ccr } = {}) {
74	  const env = { ...process.env, CLAUDINITE_REPO_ROOT: root };
75	  delete env.GITHUB_EVENT_PATH;
76	  // The suite must not inherit the CCR trigger of the session running it — that
