41	// keys: "not installed" is a state of its own, and a caller comparing against a
42	// zero or an empty string would read a fresh mount as ancient.
43	export function installedVersions(raw) {
44	  const engineVersion = isVersion(raw?.engineVersion) ? raw.engineVersion : null;
45	
46	  const packVersions = {};
47	  for (const entry of Array.isArray(raw?.packs) ? raw.packs : []) {
48	    if (entry && typeof entry === 'object' && typeof entry.id === 'string' && isVersion(entry.version)) {
49	      packVersions[entry.id] = entry.version;
50	    }
51	  }
52	  return { engineVersion, packVersions: canonicalPackVersions(packVersions) };
53	}
54	
55	// Has this repo been vendored at all? A mount that has never run stamps neither
56	// number, and every caller that used to ask "is there a stamp" is asking this.
57	export const hasInstalledMount = (raw) => {
58	  const { engineVersion, packVersions } = installedVersions(raw);
59	  return engineVersion !== null || Object.keys(packVersions).length > 0;
60	};
61	
62	// The settings object with these versions recorded: `engineVersion` at the top,
63	// each pack's version on its own entry. Returned rather than written, so the caller
64	// that owns the file owns the write — and so this stays testable without one.
65	//
66	// A version for a pack the declaration does not carry is DROPPED, not appended as
67	// a bare entry: an entry is a declaration that the pack is active, and inventing
68	// one here would activate a pack nobody declared. A pack entry declared as a plain
69	// string is widened to an object so it can hold its version; every other property
70	// and the entry ORDER survive untouched, because this file is one a person reads.
71	export function withInstalledVersions(raw, { engineVersion, packVersions } = {}) {
72	  const next = { ...(raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}) };
73	  if (engineVersion !== undefined && engineVersion !== null) next.engineVersion = engineVersion;
74	
75	  if (packVersions) {
76	    next.packs = (Array.isArray(next.packs) ? next.packs : []).map((entry) => {
77	      const id = typeof entry === 'string' ? entry : entry?.id;
78	      if (typeof id !== 'string' || !Object.hasOwn(packVersions, id)) return entry;
79	      const base = typeof entry === 'string' ? { id: entry } : { ...entry };
80	      // `version` sits directly after `id`, where a reader scanning the list for a
81	      // pack's version finds it beside the name rather than past its config. The
82	      // entry's OWN `version` is destructured out before the spread, not merely
83	      // overwritten by key order: leaving it in `rest` puts the stale number back
84	      // after the new one and freezes every member at the version it already had.
85	      const { id: entryId, version: _prior, ...rest } = base;
86	      return { id: entryId, version: packVersions[id], ...rest };
87	    });
88	  }
89	  return next;
90	}

